def minPath(grid, k):
    from collections import deque
    m, n = len(grid), len(grid[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    result = []

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            seen = set()
            queue = deque([(i, j, grid[i][j])])
            seen.add((i, j))
            while queue:
                i, j, val = queue.popleft()
                if k == 0:
                    result.append(val)
                    return result
                for dx, dy in directions:
                    new_i, new_j = i + dx, j + dy
                    if 0 <= new_i < m and 0 <= new_j < n and (new_i, new_j) not in seen:
                        seen.add((new_i, new_j))
                        queue.append((new_i, new_j, val))

    return []

