class Solution:
    def minPath(self, grid, k):
        def check_valid(i, j):
            return 0 <= i < len(grid) and 0 <= j < len(grid[0]) and grid[i][j] != -1

        def dfs(i, j, path, path_list):
            if len(path) == k:
                path_list.append(path)
                return

            directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
            for dx, dy in directions:
                ni, nj = i + dx, j + dy
                if check_valid(ni, nj):
                    dfs(ni, nj, path + [grid[ni][nj]], path_list)

        res = []
        dfs(0, 0, [], res)
        res.sort()
